/**
 * The download manager over fakes: files and manifest, formats and layouts, the budget share, resumable jobs, datasets
 * that continue from the last stored bar, local-first reads, the kill switch, a lost session, the disk limit and
 * retention. No network: the history is generated by testkit.mjs.
 */
import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { createHash } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { resetSavedCalls, snapshot as savedSnapshot } from "../market/savedCalls.mjs";
import { createFakeHistory, eventually, makeManager, TUESDAY_11AM, at, waitStatus } from "./testkit.mjs";

const started = [];
const boot = async (o) => {
  const m = makeManager(o);
  await m.manager.start();
  started.push(m.manager);
  return m;
};
beforeEach(() => resetSavedCalls());
afterEach(async () => {
  for (const m of started.splice(0)) await m.stop();
});

const jobDir = (m, id) => join(m.dataDir, "downloads", "jobs", id);
const readCsv = (file) => readFileSync(file, "utf8").split("\r\n").filter(Boolean);
const sha = (file) => createHash("sha256").update(readFileSync(file)).digest("hex");

describe("estimate (dryRun)", () => {
  it("counts broker calls, rows, bytes and time before anything starts", async () => {
    const m = await boot();
    const est = await m.manager.estimate({ symbols: ["NSE:NIFTY", "NSE:RELIANCE"], intervals: ["5m"], from: "2026-09-01", to: "2026-09-30" });
    // 22 trading days x 75 five-minute bars x 2 symbols; one broker call covers (span - 1) days
    expect(est.rows).toBeGreaterThan(2 * 20 * 75);
    expect(est.brokerCalls).toBeGreaterThanOrEqual(2);
    expect(est.bytesPerRow).toBe(62);
    expect(est.bytes).toBe(est.rows * 62);
    expect(est.budgetShare).toBe(0.3);
    expect(est.account).toBe("acc1");
    expect(est.notes.join(" ")).toMatch(/estimate|assume/i);
    expect(m.history.calls).toEqual([]);
    expect(m.manager.list()).toEqual([]);
  });

  it("refuses a job that cannot fit the disk limit", async () => {
    const m = await boot({ config: { maxDiskMb: 1 } });
    await expect(m.manager.create({ symbols: ["NSE:NIFTY"], intervals: ["1m"], from: "2020-01-01" })).rejects.toMatchObject({ code: "VALIDATION_FAILED" });
    const est = await m.manager.estimate({ symbols: ["NSE:NIFTY"], intervals: ["1m"], from: "2020-01-01" });
    expect(est.disk.wouldExceed).toBe(true);
  });
});

describe("a plain download", () => {
  it("writes one CSV per symbol and interval, a manifest with hashes and honest labels, and tells the bus", async () => {
    const m = await boot();
    const { job } = await m.manager.create({ name: "two stocks", symbols: ["NSE:RELIANCE", "NSE:INFY"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-16" });
    expect(job).toMatchObject({ status: "queued", name: "two stocks", dataClass: "realtime" });
    expect(job.manifestUrl).toBe(`/v1/downloads/${job.id}/files/manifest.json`);
    const done = await waitStatus(m.manager, job.id);
    expect(done.status).toBe("done");
    expect(done.progress).toMatchObject({ total: 2, done: 2, failed: 0 });
    const manifest = JSON.parse(readFileSync(join(jobDir(m, job.id), "manifest.json"), "utf8"));
    expect(manifest).toMatchObject({ id: job.id, name: "two stocks", status: "done", dataClass: "realtime", source: "fake", official: true, delaySec: null });
    expect(manifest.files.map((f) => f.name).sort()).toEqual(["NSE_INFY_1d.csv", "NSE_RELIANCE_1d.csv"]);
    const f = manifest.files.find((x) => x.symbol === "NSE:RELIANCE");
    expect(f.rows).toBe(12); // 1-16 October 2026: 12 weekdays
    expect(f.firstBar).toBe("2026-10-01T00:00:00.000+05:30");
    expect(f.lastBar).toBe("2026-10-16T00:00:00.000+05:30");
    const file = join(jobDir(m, job.id), f.name);
    expect(f.bytes).toBe(statSync(file).size);
    expect(f.sha256).toBe(sha(file));
    const lines = readCsv(file);
    expect(lines[0]).toBe("time,open,high,low,close,volume,oi");
    expect(lines).toHaveLength(13);
    expect(lines[1]).toMatch(/^2026-10-01,/); // daily bars carry the date only, stamped at IST midnight
    expect(m.events.map((e) => e.topic)).toContain("download.done");
    expect(m.events.find((e) => e.topic === "download.done")).toMatchObject({ id: job.id, files: 2, dataClass: "realtime" });
  });

  it("calls the broker at the lowest priority, as a background analysis read, pinned to the chosen account", async () => {
    const m = await boot();
    const { job } = await m.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-16" });
    await waitStatus(m.manager, job.id);
    expect(m.history.calls.length).toBeGreaterThan(0);
    for (const c of m.history.calls) expect(c.opts).toMatchObject({ priority: "background", purpose: "analysis", accountId: "acc1" });
    // the scheduler re-checks the product's floor (never below half of any window) when it takes the budget
    for (const c of m.history.calls) expect(c.opts.backgroundShare).toBe(0.5);
  });

  it("never stores the bar that is still forming", async () => {
    const m = await boot(); // 11:00 IST: the 5m bar that opened at 11:00 has not finished
    const { job } = await m.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["5m"], from: "2026-10-20", to: "2026-10-20" });
    await waitStatus(m.manager, job.id);
    const lines = readCsv(join(jobDir(m, job.id), "NSE_RELIANCE_5m.csv"));
    expect(lines.at(-1)).toMatch(/^2026-10-20 10:55:00,/);
    expect(lines).toHaveLength(1 + 21); // 09:15 .. 10:55 inclusive
  });

  it("writes JSONL, AmiBroker and combined layouts", async () => {
    const m = await boot();
    const a = (await m.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05", format: "jsonl" })).job;
    const b = (await m.manager.create({ symbols: ["NSE:RELIANCE", "BSE:TCS"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05", format: "amibroker" })).job;
    const c = (await m.manager.create({ name: "Both", symbols: ["NSE:RELIANCE", "NSE:INFY"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05", layout: "combined" })).job;
    for (const j of [a, b, c]) await waitStatus(m.manager, j.id);
    const jl = readFileSync(join(jobDir(m, a.id), "NSE_RELIANCE_1d.jsonl"), "utf8").trim().split("\n").map((l) => JSON.parse(l));
    expect(jl[0]).toMatchObject({ symbol: "NSE:RELIANCE", interval: "1d", time: "2026-10-01T00:00:00.000+05:30", oi: null });
    const ami = readCsv(join(jobDir(m, b.id), "BSE_TCS_1d.csv"));
    expect(ami[0]).toBe("Ticker,Date,Open,High,Low,Close,Volume,OpenInt");
    expect(ami[1]).toMatch(/^TCS\.BSE,2026-10-01,/);
    const combined = m.manager.get(c.id);
    expect(combined.status).toBe("done");
    const files = m.manager.files(c.id);
    expect(files).toHaveLength(1);
    expect(files[0]).toMatchObject({ name: "Both_1d.csv", symbol: null, interval: "1d", rows: 6 });
    const lines = readCsv(join(jobDir(m, c.id), "Both_1d.csv"));
    expect(lines[0]).toBe("symbol,time,open,high,low,close,volume,oi");
    expect(lines.filter((l) => l.startsWith("NSE:RELIANCE,"))).toHaveLength(3);
    expect(lines.filter((l) => l.startsWith("NSE:INFY,"))).toHaveLength(3);
  });

  it("labels delayed and end-of-day data and says it must not feed orders", async () => {
    const m = await boot({ history: createFakeHistory({ dataClass: "eod", source: "backup" }) });
    const { job } = await m.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05", backup: true });
    const done = await waitStatus(m.manager, job.id);
    expect(done).toMatchObject({ dataClass: "eod", delaySec: 900 });
    expect(done.notes.join(" ")).toMatch(/never be used for orders/);
    expect(m.history.calls[0].opts.allowBackup).toBe(true);
  });

  it("reports gaps: a trading day with no bars at all", async () => {
    const m = await boot({ history: createFakeHistory({ skip: (_s, t) => new Date(t * 1000).toISOString().startsWith("2026-10-14") }) });
    const { job } = await m.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["1d"], from: "2026-10-12", to: "2026-10-16" });
    const done = await waitStatus(m.manager, job.id);
    expect(done.notes.join(" ")).toMatch(/NSE:RELIANCE 1d: 1 stretch with missing bars, first at 2026-10-14/);
  });
});

describe("validation and options", () => {
  it("needs exactly one of symbols or collection, real symbols, known intervals and a sane range", async () => {
    const m = await boot();
    const bad = (body) => m.manager.estimate(body);
    await expect(bad({ intervals: ["5m"], from: "2026-01-01" })).rejects.toMatchObject({ code: "VALIDATION_FAILED" });
    await expect(bad({ symbols: ["NSE:A"], collection: "x", intervals: ["5m"], from: "2026-01-01" })).rejects.toMatchObject({ code: "VALIDATION_FAILED" });
    await expect(bad({ symbols: ["not a symbol"], intervals: ["5m"], from: "2026-01-01" })).rejects.toMatchObject({ code: "VALIDATION_FAILED" });
    await expect(bad({ symbols: ["NSE:NIFTY"], intervals: ["7m"], from: "2026-01-01" })).rejects.toMatchObject({ code: "VALIDATION_FAILED" });
    await expect(bad({ symbols: ["NSE:NIFTY"], intervals: ["5m"], from: "2026-12-01", to: "2026-11-01" })).rejects.toMatchObject({ code: "VALIDATION_FAILED" });
    await expect(bad({ symbols: ["NSE:NIFTY"], intervals: ["5m"], from: "2026-01-01", surprise: 1 })).rejects.toMatchObject({ code: "VALIDATION_FAILED" });
    await expect(bad({ symbols: ["NSE:NIFTY"], intervals: ["5m"], from: "2026-01-01", dataset: "Bad Name" })).rejects.toMatchObject({ code: "VALIDATION_FAILED" });
    await expect(bad({ symbols: ["NSE:NIFTY"], intervals: ["5m"], from: "2026-01-01", dataset: "ok", layout: "combined" })).rejects.toMatchObject({ code: "VALIDATION_FAILED" });
  });

  it("enforces downloads.maxSymbolsPerJob and the switch", async () => {
    const m = await boot({ config: { maxSymbolsPerJob: 2 } });
    await expect(m.manager.estimate({ symbols: ["NSE:A", "NSE:B", "NSE:C"], intervals: ["1d"], from: "2026-10-01" })).rejects.toThrow(/at most 2 symbols/);
    const off = await boot({ config: { enabled: false } });
    await expect(off.manager.create({ symbols: ["NSE:A"], intervals: ["1d"], from: "2026-10-01" })).rejects.toMatchObject({ code: "CAPABILITY_UNSUPPORTED" });
  });

  it("accepts a collection through the library, and says so when there is none", async () => {
    const lib = { resolve: async (name) => ({ symbols: ["NSE:RELIANCE", "NSE:INFY"], resolvedAt: "2026-10-20T10:59:00+05:30", rule: `rule for ${name}` }) };
    const m = await boot({ library: lib });
    const { job } = await m.manager.create({ collection: "my-stocks", intervals: ["1d"], from: "2026-10-01", to: "2026-10-05" });
    expect(job.request.symbols).toEqual(["NSE:RELIANCE", "NSE:INFY"]);
    expect(job.collection).toMatchObject({ name: "my-stocks", rule: "rule for my-stocks" });
    expect(job.notes[0]).toMatch(/collection "my-stocks"/);
    await waitStatus(m.manager, job.id);
    const none = await boot();
    await expect(none.manager.create({ collection: "x", intervals: ["1d"], from: "2026-10-01" })).rejects.toMatchObject({ code: "CAPABILITY_UNSUPPORTED" });
  });

  it("fails with the library's own reason when a collection cannot be resolved (a stale or delayed ATM), never a guess", async () => {
    const { BridgeError } = await import("../core/errors.mjs");
    const lib = { resolve: async () => { throw new BridgeError("BROKER_UNAVAILABLE", "The NIFTY price is delayed, so the ATM strike is not known. Try again when it is live."); } };
    const m = await boot({ library: lib });
    await expect(m.manager.create({ collection: "atm", intervals: ["5m"], from: "2026-10-01" })).rejects.toMatchObject({ code: "BROKER_UNAVAILABLE", detail: expect.stringMatching(/ATM strike is not known/) });
    await expect(m.manager.estimate({ collection: "atm", intervals: ["5m"], from: "2026-10-01" })).rejects.toMatchObject({ code: "BROKER_UNAVAILABLE" });
    expect(m.manager.list()).toEqual([]);
  });

  it("shows its jobs and datasets in a collection's usage view", async () => {
    const lib = { resolve: async () => ({ symbols: ["NSE:RELIANCE"] }) };
    const m = await boot({ library: lib });
    const { job } = await m.manager.create({ name: "from list", collection: "my-stocks", intervals: ["1d"], from: "2026-10-01", to: "2026-10-05" });
    const ds = (await m.manager.create({ collection: "my-stocks", intervals: ["1d"], from: "2026-10-01", to: "2026-10-05", dataset: "mine" })).job;
    await waitStatus(m.manager, job.id);
    await waitStatus(m.manager, ds.id);
    const u = m.manager.usageOfCollection({ name: "my-stocks", names: ["old-name"] });
    expect(u.jobs.map((x) => x.id).sort()).toEqual([job.id, ds.id].sort());
    expect(u.jobs.every((x) => x.active === false)).toBe(true);
    expect(u.datasets).toEqual([{ id: "mine", label: "mine", status: "dataset", active: false }]);
    expect(m.manager.usageOfCollection({ name: "other" })).toEqual({ jobs: [], datasets: [] });
  });

  it("keeps tags in the library's form (lower case, sorted) and filters with a list", async () => {
    const m = await boot();
    const a = (await m.manager.create({ symbols: ["NSE:A"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05", tags: ["Daily", "EQ", "daily"] })).job;
    const b = (await m.manager.create({ symbols: ["NSE:B"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05", tags: ["eq"] })).job;
    expect(a.tags).toEqual(["daily", "eq"]);
    expect(m.manager.list({ tag: "eq" }).map((j) => j.id).sort()).toEqual([a.id, b.id].sort());
    expect(m.manager.list({ tag: "eq,daily" }).map((j) => j.id)).toEqual([a.id]);
    await expect(m.manager.estimate({ symbols: ["NSE:A"], intervals: ["1d"], from: "2026-10-01", tags: ["bad tag!"] })).rejects.toMatchObject({ code: "VALIDATION_FAILED" });
  });

  it("keeps a key to its accounts", async () => {
    const m = await boot({ accounts: [{ id: "acc1", broker: "fake" }, { id: "acc2", broker: "fake" }] });
    await expect(m.manager.create({ symbols: ["NSE:A"], intervals: ["1d"], from: "2026-10-01", account: "acc2" }, { allowedAccounts: ["acc1"] })).rejects.toMatchObject({ code: "ACCOUNT_FORBIDDEN" });
    const { job } = await m.manager.create({ symbols: ["NSE:A"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05", account: "acc2" }, { allowedAccounts: ["acc2"] });
    await waitStatus(m.manager, job.id);
    expect(m.history.calls.every((c) => c.opts.accountId === "acc2" && c.opts.allowedAccounts?.[0] === "acc2")).toBe(true);
  });
});

describe("datasets", () => {
  it("continue from the last stored bar and fetch only what is new", async () => {
    let now = TUESDAY_11AM;
    const m = await boot({ clock: { now: () => now } });
    const first = (await m.manager.create({ symbols: ["NSE:RELIANCE", "NSE:INFY"], intervals: ["1d"], from: "2026-10-01", dataset: "stocks-1d" })).job;
    await waitStatus(m.manager, first.id);
    const ds = m.manager.getDataset("stocks-1d");
    expect(ds).toMatchObject({ name: "stocks-1d", format: "csv", series: 2, dataClass: "realtime", source: "fake" });
    const reliance = ds.files.find((f) => f.symbol === "NSE:RELIANCE");
    // Tuesday 11:00: the 20 October daily bar is still forming, so the dataset ends on Monday 19 October
    expect(reliance.lastBar).toBe("2026-10-19T00:00:00.000+05:30");
    expect(reliance.rows).toBe(13);
    const callsBefore = m.history.calls.length;

    now = at("2026-10-23T18:00:00+05:30"); // Friday evening: Tue, Wed, Thu, Fri are finished
    const upd = await m.manager.updateDataset("stocks-1d");
    expect(upd.existing).toBe(false);
    const done = await waitStatus(m.manager, upd.job.id);
    expect(done.status).toBe("done");
    const newCalls = m.history.calls.slice(callsBefore);
    expect(newCalls.length).toBe(2); // one window per symbol, nothing before the last stored bar
    expect(Math.min(...newCalls.map((c) => c.params.from))).toBeGreaterThanOrEqual(at("2026-10-19T00:00:00+05:30") / 1000);
    const after = m.manager.getDataset("stocks-1d").files.find((f) => f.symbol === "NSE:RELIANCE");
    expect(after.rows).toBe(17);
    expect(after.lastBar).toBe("2026-10-23T00:00:00.000+05:30");
    const lines = readCsv(join(m.dataDir, "downloads", "datasets", "stocks-1d", "NSE_RELIANCE_1d.csv"));
    expect(lines).toHaveLength(18);
    const times = lines.slice(1).map((l) => l.split(",")[0]);
    expect(new Set(times).size).toBe(times.length); // no bar twice
    expect(times).toEqual([...times].sort());
    expect(after.sha256).toBe(sha(join(m.dataDir, "downloads", "datasets", "stocks-1d", "NSE_RELIANCE_1d.csv")));
    // the dataset job's manifest lists the dataset files
    const manifest = JSON.parse(readFileSync(join(jobDir(m, upd.job.id), "manifest.json"), "utf8"));
    expect(manifest.dataset).toBe("stocks-1d");
    expect(manifest.files.map((f) => f.name).sort()).toEqual(["NSE_INFY_1d.csv", "NSE_RELIANCE_1d.csv"]);
    expect(manifest.files[0].rows).toBe(17);
  });

  it("saves the calls a full download would have made, and counts them", async () => {
    let now = TUESDAY_11AM;
    const m = await boot({ clock: { now: () => now } });
    const first = (await m.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["5m"], from: "2026-01-01", dataset: "intra" })).job;
    await waitStatus(m.manager, first.id);
    const calls1 = m.history.calls.length;
    expect(calls1).toBeGreaterThanOrEqual(5);
    now = at("2026-10-21T18:00:00+05:30");
    const upd = await m.manager.updateDataset("intra");
    const done = await waitStatus(m.manager, upd.job.id);
    expect(m.history.calls.length - calls1).toBe(1);
    expect(done.callsSaved).toBe(calls1 - 1);
    expect(savedSnapshot().byReason["dataset-incremental"]).toBe(calls1 - 1);
  });

  it("is up to date when nothing new has finished: no broker call at all", async () => {
    const m = await boot();
    const first = (await m.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["1d"], from: "2026-10-01", dataset: "one" })).job;
    await waitStatus(m.manager, first.id);
    const calls = m.history.calls.length;
    const upd = await m.manager.updateDataset("one");
    await waitStatus(m.manager, upd.job.id);
    expect(m.history.calls.length).toBe(calls);
  });

  it("answers an update that is already running with that job", async () => {
    const m = await boot({ sleep: () => new Promise((r) => setTimeout(r, 20)) });
    const first = (await m.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["1d"], from: "2026-10-01", dataset: "busy" })).job;
    await waitStatus(m.manager, first.id);
    m.history.fail("UPSTREAM_TIMEOUT", 100);
    const a = await m.manager.updateDataset("busy").catch((e) => e);
    // nothing new to fetch yet, so it may finish at once; when it is still running the same job comes back
    if (a.job && a.job.status !== "done") {
      const b = await m.manager.updateDataset("busy");
      expect(b.existing).toBe(true);
      expect(b.job.id).toBe(a.job.id);
    }
  });

  it("records the gaps inside the stored range", async () => {
    const m = await boot({ history: createFakeHistory({ skip: (_s, t) => new Date(t * 1000).toISOString().startsWith("2026-10-13") }) });
    const j = (await m.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["1d"], from: "2026-10-12", to: "2026-10-16", dataset: "gappy" })).job;
    await waitStatus(m.manager, j.id);
    const f = m.manager.getDataset("gappy").files[0];
    expect(f.gapsTotal).toBe(1);
    expect(f.gaps[0]).toMatchObject({ kind: "missing-days", missing: 1, from: "2026-10-13T00:00:00.000+05:30" });
    expect(m.manager.getDataset("gappy").gaps).toBe(1);
  });

  it("keeps a format, takes tags, renames and deletes", async () => {
    const m = await boot();
    const j = (await m.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05", dataset: "fmt", format: "csv", tags: ["daily"] })).job;
    await waitStatus(m.manager, j.id);
    await expect(m.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["1d"], from: "2026-10-01", dataset: "fmt", format: "jsonl" })).rejects.toMatchObject({ code: "VALIDATION_FAILED" });
    expect(m.manager.listDatasets({ tag: "daily" }).map((d) => d.name)).toEqual(["fmt"]);
    expect(m.manager.listDatasets({ tag: "nope" })).toEqual([]);
    const renamed = await m.manager.patchDataset("fmt", { name: "fmt2", tags: ["daily", "eq"], title: "Daily bars" });
    expect(renamed).toMatchObject({ name: "fmt2", tags: ["daily", "eq"], title: "Daily bars" });
    expect(existsSync(join(m.dataDir, "downloads", "datasets", "fmt2", "NSE_RELIANCE_1d.csv"))).toBe(true);
    expect(() => m.manager.getDataset("fmt")).toThrow(/no dataset/);
    await m.manager.removeDataset("fmt2");
    expect(existsSync(join(m.dataDir, "downloads", "datasets", "fmt2"))).toBe(false);
  });
});

describe("local first", () => {
  it("serves a stored range from disk and fetches only the missing tail", async () => {
    const m = await boot();
    const d = (await m.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-09", dataset: "base" })).job;
    await waitStatus(m.manager, d.id);
    const callsBefore = m.history.calls.length;
    const { job } = await m.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-16" });
    const done = await waitStatus(m.manager, job.id);
    expect(done.status).toBe("done");
    const fetched = m.history.calls.slice(callsBefore);
    expect(fetched.length).toBe(1); // only the part after 9 October
    expect(fetched[0].params.from).toBeGreaterThanOrEqual(at("2026-10-09T00:00:00+05:30") / 1000);
    const lines = readCsv(join(jobDir(m, job.id), "NSE_RELIANCE_1d.csv"));
    expect(lines).toHaveLength(1 + 12);
    expect(done.callsSaved).toBeGreaterThanOrEqual(1);
    expect(done.notes.join(" ")).toMatch(/came from dataset base/);
    expect(savedSnapshot().byReason["local-dataset"]).toBeGreaterThanOrEqual(1);
  });

  it("makes no broker call when the whole range is stored, and respects downloads.localFirst: false", async () => {
    const m = await boot();
    const d = (await m.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-09", dataset: "base" })).job;
    await waitStatus(m.manager, d.id);
    const before = m.history.calls.length;
    const { job } = await m.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["1d"], from: "2026-10-02", to: "2026-10-08" });
    await waitStatus(m.manager, job.id);
    expect(m.history.calls.length).toBe(before);
    expect(readCsv(join(jobDir(m, job.id), "NSE_RELIANCE_1d.csv"))).toHaveLength(1 + 5);
    const off = await boot({ config: { localFirst: false }, dataDir: m.dataDir });
    const { job: j2 } = await off.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["1d"], from: "2026-10-02", to: "2026-10-08" });
    await waitStatus(off.manager, j2.id);
    expect(off.history.calls.length).toBeGreaterThan(0);
  });
});

describe("pause, resume, cancel and restart", () => {
  it("pauses and resumes a job without repeating finished work", async () => {
    const m = await boot({ sleep: () => new Promise((r) => setTimeout(r, 15)) });
    m.history.fail("UPSTREAM_TIMEOUT", 3); // slows the first symbol so the pause lands mid-job
    const { job } = await m.manager.create({ symbols: ["NSE:A", "NSE:B", "NSE:C"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-16" });
    await eventually(() => m.manager.get(job.id).status === "running" && m.manager.get(job.id).progress.done >= 0);
    const paused = await m.manager.pause(job.id);
    expect(paused).toMatchObject({ status: "paused", reason: "user" });
    const doneAtPause = m.manager.get(job.id).progress.done;
    await expect(m.manager.pause(job.id)).rejects.toMatchObject({ code: "STATE_CONFLICT" });
    await m.manager.resume(job.id);
    const finished = await waitStatus(m.manager, job.id);
    expect(finished.status).toBe("done");
    expect(finished.progress.done).toBe(3);
    expect(doneAtPause).toBeLessThanOrEqual(3);
    for (const s of ["A", "B", "C"]) expect(existsSync(join(jobDir(m, job.id), `NSE_${s}_1d.csv`))).toBe(true);
  });

  it("continues after the Bridge restarts, from the last saved window", async () => {
    const dataDir = makeManager().dataDir;
    const m1 = await boot({ dataDir, sleep: () => new Promise((r) => setTimeout(r, 30)) });
    m1.history.fail("UPSTREAM_TIMEOUT", 1000); // the first symbol never gets through: the job is mid-way when we stop
    const { job } = await m1.manager.create({ symbols: ["NSE:A", "NSE:B"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-16" });
    await eventually(() => m1.manager.get(job.id).status === "running");
    await m1.manager.stop();
    const saved = JSON.parse(readFileSync(join(dataDir, "downloads", "jobs", job.id, "job.json"), "utf8"));
    expect(saved.status).toBe("running");
    const m2 = await boot({ dataDir });
    const again = m2.manager.get(job.id);
    expect(["queued", "running", "done"]).toContain(again.status);
    const done = await waitStatus(m2.manager, job.id);
    expect(done.status).toBe("done");
    expect(done.progress.done).toBe(2);
    expect(m2.manager.list()[0].id).toBe(job.id);
  });

  it("resumes a half-written item from its cursor and trims a cut-off part file", async () => {
    // 5m over many days needs several windows (the default span is 60 days, so 59-day windows)
    const dataDir = makeManager().dataDir;
    const m1 = await boot({ dataDir });
    const { job } = await m1.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["5m"], from: "2026-01-01", to: "2026-10-16" });
    await waitStatus(m1.manager, job.id);
    const full = readCsv(join(dataDir, "downloads", "jobs", job.id, "NSE_RELIANCE_5m.csv"));
    expect(m1.history.calls.length).toBeGreaterThanOrEqual(4);
    await m1.manager.stop();

    // Fresh folder; stop mid-item by failing every call after the second
    const dir2 = makeManager().dataDir;
    const h = createFakeHistory();
    let count = 0;
    const orig = h.history;
    h.history = async (p, o) => {
      count += 1;
      if (count === 3) await new Promise((r) => setTimeout(r, 50));
      return orig(p, o);
    };
    const m2 = await boot({ dataDir: dir2, history: h });
    const { job: j2 } = await m2.manager.create({ symbols: ["NSE:RELIANCE"], intervals: ["5m"], from: "2026-01-01", to: "2026-10-16" });
    await eventually(() => count >= 3);
    await m2.manager.pause(j2.id);
    const partial = JSON.parse(readFileSync(join(dir2, "downloads", "jobs", j2.id, "job.json"), "utf8")).items[0];
    expect(partial.rows).toBeGreaterThan(0);
    expect(partial.cursor).toBeGreaterThan(partial.fromSec);
    // a crash left half a line on the part file
    const part = join(dir2, "downloads", "jobs", j2.id, "parts", "0.part");
    writeFileSync(part, readFileSync(part, "utf8") + "2026-08-01 09:1");
    await m2.manager.resume(j2.id);
    await waitStatus(m2.manager, j2.id);
    const resumed = readCsv(join(dir2, "downloads", "jobs", j2.id, "NSE_RELIANCE_5m.csv"));
    expect(resumed).toEqual(full);
  });

  it("cancel keeps the files that were finished and drops the rest", async () => {
    const m = await boot({ sleep: () => new Promise((r) => setTimeout(r, 15)) });
    m.history.fail("UPSTREAM_TIMEOUT", 2);
    const { job } = await m.manager.create({ symbols: ["NSE:A", "NSE:B"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-16" });
    await eventually(() => m.manager.get(job.id).status === "running");
    const c = await m.manager.cancel(job.id);
    expect(c.status).toBe("cancelled");
    await expect(m.manager.cancel(job.id)).rejects.toMatchObject({ code: "STATE_CONFLICT" });
    await expect(m.manager.resume(job.id)).rejects.toMatchObject({ code: "STATE_CONFLICT" });
    expect(readdirSync(join(jobDir(m, job.id), "parts"))).toEqual([]);
  });

  it("deletes a job and its files; an unknown id is a plain not-found", async () => {
    const m = await boot();
    const { job } = await m.manager.create({ symbols: ["NSE:A"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05" });
    await waitStatus(m.manager, job.id);
    await m.manager.remove(job.id);
    expect(existsSync(jobDir(m, job.id))).toBe(false);
    expect(() => m.manager.get(job.id)).toThrow(/no download job/);
    expect(() => m.manager.get("../etc")).toThrow(/no download job/);
  });
});

describe("failures and retries", () => {
  it("retries a temporary error, then fails an item that keeps failing and lets resume try it again", async () => {
    const m = await boot({ config: { retries: 2 } });
    m.history.fail("UPSTREAM_RATE_LIMITED", 2, { retryAfterMs: 5 });
    const ok = (await m.manager.create({ symbols: ["NSE:A"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05" })).job;
    expect((await waitStatus(m.manager, ok.id)).status).toBe("done"); // 2 failures, 3rd try works

    m.history.fail("UPSTREAM_TIMEOUT", 3);
    const bad = (await m.manager.create({ symbols: ["NSE:A", "NSE:B"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05" })).job;
    const failed = await waitStatus(m.manager, bad.id);
    expect(failed.status).toBe("failed");
    expect(failed.items.map((i) => i.status)).toEqual(["failed", "done"]);
    expect(failed.items[0].error.code).toBe("UPSTREAM_TIMEOUT");
    expect(m.events.find((e) => e.topic === "download.failed" && e.id === bad.id)).toMatchObject({ failed: 1 });
    expect(m.manager.files(bad.id).map((f) => f.name)).toEqual(["NSE_B_1d.csv"]);
    await m.manager.resume(bad.id);
    const fixed = await waitStatus(m.manager, bad.id);
    expect(fixed.status).toBe("done");
    expect(m.manager.files(bad.id)).toHaveLength(2);
  });

  it("fails an item for a symbol the broker does not know without stopping the others", async () => {
    const m = await boot();
    m.history.fail("SYMBOL_NOT_FOUND", 1);
    const { job } = await m.manager.create({ symbols: ["NSE:A", "NSE:B"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05" });
    const d = await waitStatus(m.manager, job.id);
    expect(d.items[0]).toMatchObject({ status: "failed", error: { code: "SYMBOL_NOT_FOUND" } });
    expect(d.items[1].status).toBe("done");
  });
});

describe("kill switch and a lost session", () => {
  it("pauses with a clear reason when the kill switch is on, and continues when it is released", async () => {
    const m = await boot();
    m.killed.value = true;
    const { job } = await m.manager.create({ symbols: ["NSE:A"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05" });
    const p = await eventually(() => (m.manager.get(job.id).status === "paused" ? m.manager.get(job.id) : null));
    expect(p.reason).toBe("kill_switch");
    expect(p.message).toMatch(/kill switch/i);
    expect(m.history.calls).toEqual([]);
    m.killed.value = false;
    m.bus.emit("safety.kill_switch", { engaged: false });
    expect((await waitStatus(m.manager, job.id)).status).toBe("done");
  });

  it("pauses when no account can serve history and resumes at the next login", async () => {
    const m = await boot();
    m.accounts.setState("acc1", "expired");
    const { job } = await m.manager.create({ symbols: ["NSE:A"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05" });
    const p = await eventually(() => (m.manager.get(job.id).status === "paused" ? m.manager.get(job.id) : null));
    expect(p.reason).toBe("session_lost");
    expect(p.message).toMatch(/log in/i);
    m.accounts.setState("acc1", "connected");
    expect((await waitStatus(m.manager, job.id)).status).toBe("done");
  });

  it("pauses when the broker says the session ended in the middle of a window", async () => {
    const m = await boot();
    m.history.fail("SESSION_EXPIRED", 1);
    const { job } = await m.manager.create({ symbols: ["NSE:A"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05" });
    const p = await eventually(() => (m.manager.get(job.id).status === "paused" ? m.manager.get(job.id) : null));
    expect(p.reason).toBe("session_lost");
    await m.manager.resume(job.id);
    expect((await waitStatus(m.manager, job.id)).status).toBe("done");
  });
});

describe("disk limit and retention", () => {
  it("stops writing at the disk limit with a clear reason; resume works once there is room", async () => {
    const m = await boot({ config: { maxDiskMb: 1 } });
    const { job } = await m.manager.create({ symbols: ["NSE:A", "NSE:B"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-16" });
    await waitStatus(m.manager, job.id);
    // fill the folder behind the manager's back, then a second job hits the limit
    writeFileSync(join(m.dataDir, "downloads", "filler.bin"), Buffer.alloc(1024 * 1024));
    await m.manager.stop();
    const m2 = await boot({ config: { maxDiskMb: 1 }, dataDir: m.dataDir });
    await expect(m2.manager.create({ symbols: ["NSE:C"], intervals: ["5m"], from: "2026-10-01", to: "2026-10-16" })).rejects.toThrow(/disk|limit|MB/i);
    const small = await m2.manager.estimate({ symbols: ["NSE:C"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05" });
    expect(small.disk.usedBytes).toBeGreaterThan(1024 * 1024);
  });

  it("fails the job when a write would pass the limit", async () => {
    const m = await boot({ config: { maxDiskMb: 1 } });
    const { job } = await m.manager.create({ symbols: ["NSE:A"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05" });
    await waitStatus(m.manager, job.id);
    m.manager.internals.jobs.get(job.id); // finished
    writeFileSync(join(m.dataDir, "downloads", "filler.bin"), Buffer.alloc(1024 * 1024 - 100));
    await m.manager.stop();
    const m2 = await boot({ config: { maxDiskMb: 1 }, dataDir: m.dataDir });
    const created = await m2.manager.create({ symbols: ["NSE:B"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-16" }).catch((e) => e);
    if (created.job) {
      const d = await waitStatus(m2.manager, created.job.id);
      expect(d).toMatchObject({ status: "failed", reason: "disk_limit" });
      expect(d.message).toMatch(/downloads.maxDiskMb/);
      expect(m2.events.find((e) => e.topic === "download.failed")).toMatchObject({ reason: "disk_limit" });
    } else expect(created.code).toBe("VALIDATION_FAILED");
  });

  it("retention deletes finished jobs older than retentionDays and never a dataset", async () => {
    let now = TUESDAY_11AM;
    const m = await boot({ clock: { now: () => now }, config: { retentionDays: 7 } });
    const a = (await m.manager.create({ symbols: ["NSE:A"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05" })).job;
    const b = (await m.manager.create({ symbols: ["NSE:A"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05", dataset: "keep" })).job;
    await waitStatus(m.manager, a.id);
    await waitStatus(m.manager, b.id);
    expect(await m.manager.sweepRetention()).toEqual([]);
    now += 8 * 86_400_000;
    const gone = await m.manager.sweepRetention();
    expect(gone.sort()).toEqual([a.id, b.id].sort());
    expect(existsSync(jobDir(m, a.id))).toBe(false);
    expect(m.manager.getDataset("keep").series).toBe(1);
  });
});

describe("the budget share", () => {
  it("waits between calls so downloads stay within their share of the per-second budget", async () => {
    const waits = [];
    let t = 1_000_000;
    const m = await boot({ clock: { now: () => TUESDAY_11AM }, sleep: async (ms) => { waits.push(ms); t += ms; await new Promise((r) => setImmediate(r)); } });
    // a tight window: 5 calls a second, share 0.3 => one call every 667 ms
    m.scheduler.headroomWindows = () => ({ windows: [{ bucket: "history", window: "1s", used: 0, limit: 5, remaining: 5, resetMs: 0 }], backoffMs: 0 });
    const origNow = Date.now;
    Date.now = () => t;
    try {
      const { job } = await m.manager.create({ symbols: ["NSE:A", "NSE:B", "NSE:C"], intervals: ["1d"], from: "2026-10-01", to: "2026-10-05" });
      await waitStatus(m.manager, job.id);
    } finally {
      Date.now = origNow;
    }
    expect(m.history.calls.length).toBe(3);
    expect(waits.length).toBeGreaterThanOrEqual(2);
    for (const w of waits) expect(w).toBeGreaterThan(0);
  });
});
